package com.zomiggy.controller; import com.zomiggy.dto.ApiDtos.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/assistant") public class AssistantController { @PostMapping("/messages") public Map<String,Object> message(@Valid @RequestBody AssistantRequest r){String q=r.message().toLowerCase();String text=q.contains("coupon")||q.contains("discount")?"Try ZOMNEW, 50OFF, PARTY150, TASTY30, or FREEDEL in your cart.":q.contains("order")||q.contains("where")?"Your latest order is being processed. Open tracking for the live route.":q.contains("healthy")?"Browse the healthy choices marked in the menu.":"Browse restaurants and cuisine filters on Home to explore the menu.";return Map.of("message",text,"dishes",List.of(),"actions",List.of());} }